\[
\bar M_{\mathrm n}
=\frac{\int_{M_1}^{M_2}W\,dM}{\int_{M_1}^{M_2}(W/M)\,dM}
=\frac{M_2-M_1}{\ln(M_2/M_1)}
\approx 2.15\times10^4,
\]

\[
